import sys, threading, json, urllib.error
from http.server import HTTPServer, BaseHTTPRequestHandler
sys.path.insert(0, '.')
import weather, importlib; importlib.reload(weather)
state={'fails':0,'hits':0,'code':503}
class H(BaseHTTPRequestHandler):
    def log_message(self,*a): pass
    def do_GET(self):
        state['hits']+=1
        if state['hits']<=state['fails']:
            self.send_response(state['code']); self.end_headers(); return
        b=json.dumps({'ok':True}).encode(); self.send_response(200); self.send_header('Content-Length',str(len(b))); self.end_headers(); self.wfile.write(b)
srv=HTTPServer(('127.0.0.1',0),H); threading.Thread(target=srv.serve_forever,daemon=True).start()
c=weather.WeatherClient(f'http://127.0.0.1:{srv.server_port}', backoff=0.01)
def run(fails, code=503):
    state.update(fails=fails,hits=0,code=code)
    try: r=c.get('x')
    except urllib.error.HTTPError as e: r=f'HTTPError {e.code}'
    return r, state['hits']
print(run(0)); print(run(2)); print(run(3)); print(run(1,500))
srv.shutdown()

